import { unitGuideSections } from './unit-guide.js';
const E = (spanish, english, tense = 'mixed') => ({ spanish, english, tense });
const B = (heading, body, examples = [], tip = '', table) => ({ heading, body, examples, tip, ...(table ? { table } : {}) });
const persons = ['yo', 'tú', 'él / ella / usted', 'nosotros/as', 'vosotros/as', 'ellos / ellas / ustedes'];
const conjugations = (headers, columns) => ({ headers: ['Person', ...headers], rows: persons.map((person, i) => [person, ...columns.map(column => column[i])]) });

export const guideSections = [
  {
    id: 'perspective', title: 'Two ways of looking at the past', subtitle: 'The same situation, a different viewpoint', diagram: 'perspective',
    intro: 'Spanish does more than locate an event in the past. It lets you choose how to present it: from inside a situation, or as a bounded whole. This choice is called aspect.',
    blocks: [
      B('Look from inside: the imperfect', 'The imperfect places your viewpoint inside a past situation. It shows what was happening, what someone was like, or what usually happened. It does not assert the beginning or endpoint. This does not mean the situation continues today: its boundaries are simply outside the picture.', [E('A las seis, Marta preparaba la cena.', 'At six, we look inside the preparation. We are not told when it began or ended.', 'imperfect'), E('Mi abuelo vivía en Valencia cuando era joven.', 'This recalls his life then. It does not claim that he still lives there.', 'imperfect')], 'Ask “What was the situation like at that point?”, rather than whether it is still true today.'),
      B('Look at the whole: the preterite', 'The preterite, also called pretérito indefinido or pretérito perfecto simple, presents an event, state or series as a bounded whole. The boundaries may come from the words, the story or shared knowledge. A whole episode can last seconds or many years. Shortness is not the rule.', [E('Marta preparó la cena y llamó a sus amigos.', 'The preparation is a complete event, followed by the call.', 'preterite'), E('Mi abuelo vivió en Valencia durante cuarenta años.', 'Forty years form the complete period being presented.', 'preterite')], 'A closed view does not mean a quick or sudden action. Even a long state can be presented as a whole.'),
      B('Sometimes both are natural', 'Changing the tense can change the viewpoint without making the sentence ungrammatical. Read the surrounding text and consider the intended meaning. When a natural alternative fits the context in this collection, it earns full credit and receives its own explanation.', [E('Aquella tarde llovía mucho.', 'We picture the rain from within that afternoon, perhaps as background.', 'imperfect'), E('Aquella tarde llovió mucho.', 'We sum up the rainfall over the afternoon as an episode.', 'preterite')], 'Ayer, aquella tarde and en 2020 locate something in time; they do not select a tense on their own.')
    ], practice: ['scene-readings', 'alternatives'], sources: [{ title: 'RAE–ASALE · Aspecto perfectivo', url: 'https://temporalweb.asale.org/gtg/aspecto-perfectivo' }]
  },
  {
    id: 'scene', title: 'A scene and the events inside it', subtitle: 'What was happening when something happened?', diagram: 'scene',
    intro: 'Stories often combine an ongoing situation with an event. The imperfect opens a window onto the situation; the preterite introduces an event seen as a whole.',
    blocks: [
      B('Background and an event', 'Weather, surroundings, feelings and ongoing activities often provide background. A new event can happen within that scene. It does not necessarily stop the activity: the sentence tells us about their relationship, not automatically about an interruption.', [E('Hacía frío y esperábamos el autobús. De pronto, llegó Ana.', 'The cold and waiting set the scene. Ana’s arrival adds an event.'), E('Mientras cocinaba, sonó el teléfono.', 'The phone rang during the cooking. We do not know whether the cooking stopped.')], '“The preterite interrupts the imperfect” is only one possible relationship. Sometimes the activities simply overlap.'),
      B('The viewpoint changes the sequence', 'With cuando, the tense helps establish how events relate. Cuando itself does not require either tense. Compare being partway through crossing with presenting the crossing as a complete step. The rest of the context can make the sequence more precise.', [E('Cuando cruzaba la plaza, vi a Luis.', 'I saw Luis while crossing: my viewpoint is inside the crossing.'), E('Cuando crucé la plaza, vi a Luis.', 'The crossing is presented as a complete step linked to seeing Luis.', 'preterite')]),
      B('Two activities can overlap', 'The imperfect can show two activities unfolding together. The preterite can sum up what each person accomplished during a shared period. The intended view matters more than identifying a “signal word”.', [E('Yo ordenaba la cocina mientras Pablo lavaba los platos.', 'We watch both activities in progress.', 'imperfect'), E('Durante esa hora, Pablo lavó los platos y yo ordené toda la cocina.', 'Both accomplishments are presented as complete.', 'preterite')], 'Mientras commonly introduces an ongoing background, but it is not an automatic imperfect detector.')
    ], practice: ['scene-readings', 'process', 'surprises']
  },
  {
    id: 'duration', title: 'A whole period or a moment within it?', subtitle: 'Duration is about viewpoint, not length', diagram: 'duration',
    intro: 'A five-minute activity and a twenty-year situation can both be viewed from inside or presented as a complete period.',
    blocks: [
      B('Present the complete duration', 'When you tell us how long a particular episode lasted, the preterite normally presents that complete episode. Durante dos horas or hasta las ocho can establish its limits. The focus is the whole period, however long it lasted.', [E('Ayer trabajé desde las nueve hasta las seis.', 'The sentence measures one complete working period.', 'preterite'), E('Estuvimos esperando cuarenta minutos y al final nos fuimos.', 'The whole wait is bounded by leaving.', 'preterite')], 'Estuve + gerund works for a complete period of activity. A progressive construction does not automatically require the imperfect.'),
      B('Look inside the same period', 'Use the imperfect to show what was in progress at a reference moment inside the episode. These sentences can describe the same real events. They answer different questions: “What happened over the whole period?” and “What was happening at that moment?”', [E('A las cinco todavía trabajaba.', 'Five o’clock is a point inside the working period.', 'imperfect'), E('Cuando nos llamó Laura, estábamos esperando el autobús.', 'The call locates a moment inside the wait.')]),
      B('Read what the duration measures', 'Duration expressions do not act as tense switches. A phrase may measure each repeated session or frame a situation seen from inside a larger period. Find out whether the speaker measures a complete episode or describes what usually happened.', [E('Durante aquel verano trabajaba dos horas cada mañana.', 'Two hours describes each usual session inside the summer routine.', 'imperfect'), E('Aquel verano trabajé en la biblioteca durante dos meses.', 'The two-month job is one complete episode.', 'preterite')])
    ], practice: ['process', 'duration', 'alternatives']
  },
  {
    id: 'description', title: 'People, states and complete experiences', subtitle: '¿Cómo era? and ¿Cómo fue?',
    intro: 'Descriptions often use the imperfect; evaluations of complete experiences often use the preterite. This comes from the viewpoint, rather than a list of “description verbs”.',
    blocks: [
      B('Recall a person, place or state', 'The imperfect recalls someone’s characteristics or the state of something at a past moment. Ser, estar and tener follow the same viewpoint distinction as other verbs. None belongs exclusively to one past tense.', [E('La profesora era paciente y tenía mucha energía.', 'These qualities describe the teacher in the remembered situation.', 'imperfect'), E('Cuando entré, la sala estaba vacía.', 'The room’s state is background at the moment of entry.')]),
      B('Evaluate a complete experience', 'The preterite commonly sums up a journey, concert, conversation or day. A person can also appear with the preterite when the speaker evaluates their behaviour during a particular encounter.', [E('El concierto fue emocionante.', 'An overall evaluation of the concert.', 'preterite'), E('Durante la entrevista, la directora fue muy amable conmigo.', 'An evaluation of her behaviour in that encounter.', 'preterite')], 'Era amable describes a characteristic from inside the remembered situation. Fue amable can evaluate behaviour on a particular occasion.'),
      B('States can have boundaries too', 'The preterite can present a state across a whole period; the imperfect can place us inside that same state. Qualities are not restricted to the imperfect. For example, a hairstyle can be recalled as a characteristic or presented as a complete stage.', [E('De joven, Elena tenía el pelo largo.', 'Her hair is part of the description of that stage.', 'imperfect'), E('Elena tuvo el pelo largo diez años; después se lo cortó.', 'The entire ten-year period is bounded.', 'preterite')])
    ], practice: ['descriptions', 'duration', 'writing']
  },
  {
    id: 'habits', title: 'Habits and counted occasions', subtitle: 'Repetition can be open or bounded', diagram: 'habits',
    intro: 'Both tenses can describe repeated actions. The imperfect presents a routine within a past period; the preterite can sum up a complete series of occasions.',
    blocks: [
      B('Describe the routine', 'The imperfect tells us what someone used to do or what normally happened. We are not counting a complete series. Normalmente, cada día and a menudo often help establish this reading, but the overall interpretation remains the deciding factor.', [E('Cuando éramos pequeños, íbamos a la playa los domingos.', 'Going to the beach is a childhood routine.', 'imperfect'), E('Mi vecina leía un rato antes de acostarse.', 'This describes her usual practice in the remembered period.', 'imperfect')]),
      B('Sum up the occasions', 'The preterite can present a specific number of occasions or a complete series within a bounded period. Repetition does not have to use the imperfect: the series itself can be treated as a whole.', [E('El verano pasado fuimos a la playa cuatro veces.', 'The speaker counts four complete visits within last summer.', 'preterite'), E('Durante aquella semana llamé a mi madre todos los días.', 'The calls form a complete series over one particular week.', 'preterite')]),
      B('Siempre and nunca need context', 'Frequency words do not choose the tense independently. Siempre can describe a habitual picture or sum up a whole period. Nunca can describe a recurring pattern or say that an event never occurred throughout the relevant period.', [E('De niño, siempre llegaba pronto al colegio.', 'Usual behaviour from within childhood.', 'imperfect'), E('Durante los tres días del curso, siempre llegué pronto.', 'A complete set of arrivals over those three days.', 'preterite')], 'Ask whether the series is presented from within or closed and summed up. Do not search for one “magic word”.')
    ], practice: ['habits', 'alternatives', 'writing']
  },
  {
    id: 'narrative', title: 'Build a story with depth', subtitle: 'A sequence, a setting and a reason',
    intro: 'A lively account combines main events with surroundings, reasons, feelings and activities in progress. The tenses let the narrator move between summary and close-up.',
    blocks: [
      B('Set the scene, then change something', 'The imperfect establishes what you want the reader to imagine at a reference point. The preterite presents events that change the situation or form the main sequence. Those events can include long activities and states, not just sudden actions.', [E('Eran las once. La calle estaba vacía y yo volvía a casa.', 'Time, surroundings and an ongoing journey build the scene.', 'imperfect'), E('De pronto, oí un golpe, me paré y miré hacia una puerta.', 'Three events advance the account.', 'preterite')]),
      B('Explain without advancing the clock', 'After an event, the imperfect can help explain the situation at that moment. It adds a reason, a feeling or simultaneous activity rather than necessarily giving the next chronological step. This is why reading the entire paragraph helps.', [E('No abrí la puerta porque tenía miedo. Dentro, alguien movía una silla.', 'The fear explains the decision. The moving chair is heard as an ongoing activity.'), E('Entonces salió mi vecino. Llevaba una caja y sonreía.', 'His appearance advances the story; the following details describe him then.')], 'The imperfect does not say that the fear or smile lasted forever. Their endpoints are simply not the focus.'),
      B('Finish with a summary or a final picture', 'A closing evaluation often uses the preterite; a final close-up can use the imperfect. Choose what you want the reader to see. There is no rule requiring every “action verb” to be preterite or every descriptive word to belong to the imperfect.', [E('Al final, nos reímos del susto y seguimos hablando diez minutos.', 'The final events and the complete conversation are summed up.', 'preterite'), E('Cuando llegué a mi piso, todavía sonreía.', 'The narrator ends with a close-up of their state on arriving.')])
    ], practice: ['background', 'surprises', 'writing']
  },
  {
    id: 'meaning', title: 'When the viewpoint changes the meaning', subtitle: 'Knowing, meeting, wanting and having',
    intro: 'Some verbs have familiar interpretations in particular contexts. These patterns help, but they are not fixed translations that replace reading the sentence.',
    blocks: [
      B('Sabía / supe and conocía / conocí', 'Sabía presents knowledge already held at the reference moment. Supe often presents the discovery of information. Conocía describes existing familiarity; conocí often introduces a first meeting or the acquisition of familiarity. Conocí can also summarise acquaintance over a whole period.', [E('Ya sabía la dirección cuando salimos.', 'Existing knowledge is part of the situation.'), E('Supe la noticia al abrir el mensaje.', 'Opening the message is when the information became known.', 'preterite'), E('Conocía a Inés del colegio; conocí a su hermana el sábado.', 'Existing acquaintance contrasts with a first meeting.')], 'Conocí bien aquella ciudad durante mis años allí sums up a period of familiarity. Conocí does not always mean one brief meeting.'),
      B('Quería / quise', 'Quería commonly presents an existing wish or intention. Quise presents a wish or intention as a bounded occurrence and can suggest a decision or attempt in context. No quise often expresses refusal. “Tried” and “refused” are contextual interpretations, not automatic translations.', [E('Quería hablar con Ana, pero no sabía su número.', 'The wish is background to the difficulty.', 'imperfect'), E('Quise abrir la ventana, pero no pude.', 'This context presents a particular attempt.', 'preterite'), E('Me ofrecieron ayuda, pero no quise aceptarla.', 'The response naturally expresses a refusal on that occasion.', 'preterite')]),
      B('Tenía / tuve', 'Tenía describes a possession, condition or obligation from inside a situation. Tuve can bound that state or episode. It does not always mean “got”: tuve fiebre can simply summarise a period of illness. With tener que, compare an existing obligation with a particular obligation episode.', [E('Cuando me llamaste, tenía fiebre.', 'The fever is the condition at the reference moment.'), E('Tuve fiebre dos días y después mejoré.', 'The complete period of illness is bounded.', 'preterite'), E('Tenía que trabajar esa tarde, así que no fui al cine.', 'An obligation already in place explains the decision.'), E('El coche no arrancó y tuve que volver andando.', 'The obligation is a particular development in the account.', 'preterite')])
    ], practice: ['alternatives', 'surprises', 'writing']
  },
  ...unitGuideSections,
  {
    id: 'forms', title: 'Conjugation reference', subtitle: 'Conjugation, accents and additional forms',
    intro: 'Decide what you want to express, then choose the form that agrees with the subject. Use these tables as a reference. The optional story challenges introduce other forms you have studied.',
    blocks: [
      B('Regular imperfect and preterite', 'Only ser, ir and ver are irregular in the imperfect. All regular -er and -ir imperfect endings have an accent on í. In the regular preterite, check first- and third-person singular accents. Nosotras and vosotras take the same endings as nosotros and vosotros.', [], 'Hablamos and vivimos can be present or preterite: context distinguishes them. Tú forms end in hablaste and comiste, without a final s.', conjugations(['hablar · imp.', 'comer · imp.', 'vivir · imp.', 'hablar · pret.', 'comer · pret.', 'vivir · pret.'], [ ['hablaba','hablabas','hablaba','hablábamos','hablabais','hablaban'], ['comía','comías','comía','comíamos','comíais','comían'], ['vivía','vivías','vivía','vivíamos','vivíais','vivían'], ['hablé','hablaste','habló','hablamos','hablasteis','hablaron'], ['comí','comiste','comió','comimos','comisteis','comieron'], ['viví','viviste','vivió','vivimos','vivisteis','vivieron'] ])),
      B('The three irregular imperfect verbs', 'Learn these complete patterns. Remember éramos, íbamos and the accent in every form of veía. In existential “there was / there were”, use había with both singular and plural nouns.', [E('Había una silla. Había tres sillas.', 'The existential verb stays singular in both sentences.', 'imperfect')], '', conjugations(['ser', 'ir', 'ver'], [['era','eras','era','éramos','erais','eran'],['iba','ibas','iba','íbamos','ibais','iban'],['veía','veías','veía','veíamos','veíais','veían']])),
      B('Common irregular preterite stems', 'These stems take -e, -iste, -o, -imos, -isteis, -ieron, without written accents. After j, the final ending is -eron: dijeron, trajeron. Hacer changes spelling in hizo. Learn a stem together with its subject. Existential haber is normally practised as hubo: hubo una charla; hubo varias charlas.', [], '', { headers: ['Infinitive','Stem','yo','él / ella','ellos / ellas'], rows: [['estar','estuv-','estuve','estuvo','estuvieron'],['tener','tuv-','tuve','tuvo','tuvieron'],['poder','pud-','pude','pudo','pudieron'],['poner','pus-','puse','puso','pusieron'],['saber','sup-','supe','supo','supieron'],['querer','quis-','quise','quiso','quisieron'],['venir','vin-','vine','vino','vinieron'],['hacer','hic- / hiz-','hice','hizo','hicieron'],['decir','dij-','dije','dijo','dijeron'],['traer','traj-','traje','trajo','trajeron']] }),
      B('Ser, ir, dar, ver and existential haber', 'Ser and ir share the preterite forms; context tells you which verb is intended. Dar and ver have no written accents in these forms. Existential hubo presents an occurrence or bounded situation and remains singular: hubo un problema; hubo varios problemas.', [E('Había mucho ruido cuando entramos. Después hubo un silencio.', 'The noise describes the scene; the silence is a development.')], '', conjugations(['ser / ir','dar','ver'], [['fui','fuiste','fue','fuimos','fuisteis','fueron'],['di','diste','dio','dimos','disteis','dieron'],['vi','viste','vio','vimos','visteis','vieron']])),
      B('Spelling, stem changes and accents', 'Some changes preserve pronunciation: busqué, llegué, empecé. Compare buscó, llegó, empezó. Notice leí, leíste, leyó, leímos, leísteis, leyeron and caí, cayó. In these common -ir verbs, the preterite vowel change appears only in the third persons: e becomes i in pedir and sentir; o becomes u in dormir. Do not transfer the present-tense pattern to every person: sentí, not sintí. This is a pattern for these verbs, not a claim that all -ir verbs change.', [E('Yo pedí ayuda y mis compañeros pidieron una silla.', 'Compare first-person pedí with third-person pidieron.', 'preterite'), E('Sentí alegría cuando vi a mi hermana. Ella también sintió una emoción enorme.', 'Sentir changes to sint- in third-person sintió, but yo keeps sent-.', 'preterite')], 'An accent-only error earns half a point here. Ñ is a different letter from n. A written accent can distinguish hablo from habló.', conjugations(['pedir · pret.','sentir · pret.','dormir · pret.'], [['pedí','pediste','pidió','pedimos','pedisteis','pidieron'],['sentí','sentiste','sintió','sentimos','sentisteis','sintieron'],['dormí','dormiste','durmió','dormimos','dormisteis','durmieron']])),
      B('Present and present perfect', 'The present can describe a current fact or habit. The present perfect uses present haber —he, has, ha, hemos, habéis, han— plus an unchanged participle: hablado, comido, vivido. Useful irregular participles include hecho, dicho, visto, puesto, vuelto, escrito and abierto.', [E('Ahora trabajo en un museo, pero antes trabajaba en una tienda.', 'The current situation contrasts with the earlier one.'), E('Esta semana he visitado el museo dos veces.', 'The visits connect with the current week.')], 'Many speakers in Spain favour the present perfect for a period connected with now. Many other regions naturally use the preterite in similar contexts. Relevant alternatives are accepted; this is not a universal right/wrong distinction.'),
      B('Affirmative instructions: who is addressed?', 'Direct quotations in a past story can contain commands. Choose the form for the person being addressed, rather than the narrator. Regular affirmative tú forms are habla, come, vive. For vosotros, replace final r with d. Regular usted commands use -e for -ar verbs and -a for -er/-ir verbs; ustedes adds n. A respectful singular address such as señora uses usted.', [E('La recepcionista me dijo: «Pasa y espera aquí». Luego habló con mi padre: «Pase, señor Ruiz».', 'The narration is past; the direct commands change with tú or usted.')], 'These activities practise affirmative commands. A command does not become a past tense just because it is quoted inside a past story.', { headers: ['Infinitive','tú','usted','vosotros/as','ustedes'], rows: [['hablar','habla','hable','hablad','hablen'],['comer','come','coma','comed','coman'],['vivir','vive','viva','vivid','vivan']] }),
      B('Eight useful irregular commands and vowel changes', 'Learn the eight frequent irregular affirmative tú forms together with their infinitives. Usted forms include ponga, haga, tenga and diga; ser and ir give sea and vaya. Present vowel changes also appear in common tú and usted commands: piensa / piense, duerme / duerma, pide / pida. Compare vosotros pensad, dormid and pedid, which do not use those stem changes.', [E('Mi abuela me miró y dijo: «Pon la mesa y ven conmigo».', 'Two irregular tú commands appear in direct speech.'), E('El empleado se dirigió a una clienta: «Venga conmigo y pida su tarjeta aquí».', 'The respectful singular commands are addressed to usted.')], 'Ustedes commands normally add n to the usted form: pongan, hagan, vengan, digan, sean, vayan. This is separate from the vosotros forms used in Spain.', { headers: ['Infinitive','tú','usted','vosotros/as'], rows: [['decir','di','diga','decid'],['hacer','haz','haga','haced'],['ir','ve','vaya','id'],['poner','pon','ponga','poned'],['salir','sal','salga','salid'],['ser','sé','sea','sed'],['tener','ten','tenga','tened'],['venir','ven','venga','venid']] }),
      B('Attach pronouns to affirmative commands', 'Put the pronoun after an affirmative command and write the result as one word: dime, dígame, levántate, siéntese. Keep the original stress, adding a written accent when the spelling rules require it. With vosotros and attached os, the d normally disappears: lavad + os → lavaos; sentad + os → sentaos. Check both the form of address and the attached pronoun.', [E('La enfermera le dijo: «Siéntese aquí y dígame su nombre».', 'Usted commands take attached se and me, with accents to preserve the stress.'), E('La profesora dijo a sus alumnos: «Lavaos las manos y poneos los delantales».', 'Vosotros commands drop d before os: lavaos, poneos.')], 'Compare dime for tú and dígame for usted. In these affirmative commands, me diga and se siente do not have the required pronoun position.'),
      B('Health, feelings and locations', 'With doler, the painful body part controls agreement: me duele la rodilla / me duelen los pies; in the imperfect, me dolía / me dolían. The pronoun tells us who feels the pain. Tener introduces symptoms such as fiebre or tos; estar can describe conditions such as enfermo, mareada, nervioso or contenta. Ser identifies or characterises someone; estar normally locates people and objects. For the location of an event, Spanish uses ser.', [E('Me dolían los pies y estaba cansada; por eso volví despacio.', 'Plural pies requires dolían. The pain and tiredness explain the slow return.'), E('Su cocina estaba en el centro de la casa y era muy luminosa.', 'Estaba gives the location; era describes a characteristic.'), E('La charla fue en el patio; el proyector estaba en una mesa.', 'The location of an event uses ser; the location of an object uses estar.')], 'Avoid assigning one past tense to ser, estar, tener or doler automatically. Their viewpoint still depends on the account: estaba nerviosa describes a state then; estuvo nerviosa toda la entrevista sums up the whole interval.'),
      B('Periphrases: keep the infinitive or gerund', 'With tener que + infinitive and ir a + infinitive, conjugate the first verb; the infinitive stays unchanged. Tenía que salir presents an existing obligation; tuve que salir presents a particular obligation episode. Iba a salir presents a plan or imminent departure without itself saying whether it happened.', [E('Iba a salir cuando llamó mi hermana.', 'A planned or imminent departure is background to the call.'), E('Estaba leyendo cuando llegaste. Ayer estuve leyendo dos horas.', 'Estaba looks inside; estuve presents the whole two-hour activity.')], 'Form the gerund with -ando or -iendo: hablando, comiendo, viviendo. Common changes include leyendo, durmiendo and yendo. If a blank requests a multiword form, include every required word.')
    ], practice: ['verb-warmup','progressive-past','voices-and-reactions','process','duration','writing']
  }
];
